-- antrian_bioskop_complete\nCREATE DATABASE IF NOT EXISTS `antrian_bioskop` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;\nUSE `antrian_bioskop`;\nCREATE TABLE IF NOT EXISTS `users` (\n  `id` INT AUTO_INCREMENT PRIMARY KEY,\n  `username` VARCHAR(100) NOT NULL UNIQUE,\n  `password` VARCHAR(255) NOT NULL,\n  `role` ENUM('admin','petugas') NOT NULL,\n  `name` VARCHAR(150) DEFAULT NULL\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\nINSERT INTO users (username,password,role,name) VALUES ('admin','0192023a7bbd73250516f069df18b500','admin','Administrator'),('petugas','570c396b3fc856eceb8aa7357f32af1a','petugas','Petugas Loket');\nCREATE TABLE IF NOT EXISTS `films` (\n  `id` INT AUTO_INCREMENT PRIMARY KEY,\n  `title` VARCHAR(200) NOT NULL,\n  `duration` VARCHAR(50) DEFAULT NULL,\n  `show_date` DATE DEFAULT NULL\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\nINSERT INTO films (title,duration,show_date) VALUES ('Venom 3: The Last Dance','120 min',NULL),('Deadpool & Wolverine','110 min',NULL),('Inside Out 2','95 min',NULL),('Despicable Me 4','100 min',NULL);\nCREATE TABLE IF NOT EXISTS `counters` (\n  `id` INT AUTO_INCREMENT PRIMARY KEY,\n  `name` VARCHAR(100) NOT NULL\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\nINSERT INTO counters (name) VALUES ('Loket 1'), ('Loket 2');\nCREATE TABLE IF NOT EXISTS `tickets` (\n  `id` INT AUTO_INCREMENT PRIMARY KEY,\n  `code` VARCHAR(30) NOT NULL UNIQUE,\n  `name` VARCHAR(150) DEFAULT 'Pengunjung',\n  `film_id` INT NOT NULL,\n  `status` ENUM('waiting','serving','done','skipped') DEFAULT 'waiting',\n  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  `served_at` TIMESTAMP NULL DEFAULT NULL,\n  `counter_id` INT NULL,\n  FOREIGN KEY (film_id) REFERENCES films(id) ON DELETE RESTRICT,\n  FOREIGN KEY (counter_id) REFERENCES counters(id) ON DELETE SET NULL\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\n